import{_ as e,o as t,c as r,Q as a}from"./chunks/framework.b67c47e6.js";const o="/assets/sticker-a4-4.bde87a31.svg",s="/assets/sticker-a4-12.3f274f78.svg",n="/assets/sticker-rack-load.4e8a677c.svg",f=JSON.parse('{"title":"QR Stickers","description":"","frontmatter":{},"headers":[],"relativePath":"guide/reports/qr_stickers/index.md","filePath":"guide/reports/qr_stickers/index.md","lastUpdated":1790354386000}'),i={name:"guide/reports/qr_stickers/index.md"},l=a('<h1 id="qr-stickers" tabindex="-1">QR Stickers <a class="header-anchor" href="#qr-stickers" aria-label="Permalink to &quot;QR Stickers&quot;">​</a></h1><p>The QR Stickers report generates printable QR code labels that can be attached to physical constructibles (assemblies and modules) for quick identification on the shop floor. It is listed under <em>Labels and Stickers</em> in the report type list of a project&#39;s <strong>Production files</strong>, next to <strong>Rack Load Stickers</strong> (see <a href="#rack-load-stickers">below</a>).</p><h2 id="output" tabindex="-1">Output <a class="header-anchor" href="#output" aria-label="Permalink to &quot;Output&quot;">​</a></h2><ul><li><strong>Format:</strong> PDF with <strong>By Selected Panels</strong>; a ZIP with one PDF per phase, batch or panel with the other <strong>Make files</strong> options.</li><li><strong>Content:</strong> One sticker per selected constructible, sorted by phase, batch and order in batch. Each QR code links to the constructible&#39;s Viewer page, and in the PDF the QR is also a clickable link. Each sticker prints the project name and number, phase, batch, order in batch, date, the design name (with its revision when it is not 0) and a short panel ID (the first 8 characters of the panel&#39;s unique identifier), so panels can be identified by eye without scanning. The banner formats also print the client name.</li></ul><h2 id="options" tabindex="-1">Options <a class="header-anchor" href="#options" aria-label="Permalink to &quot;Options&quot;">​</a></h2><table><thead><tr><th>Option</th><th>Description</th></tr></thead><tbody><tr><td><strong>Make files</strong></td><td><em>By Batch</em> (default), <em>By Phase</em>, <em>By Panel</em> or <em>By Selected Panels</em>: how the stickers are split into files.</td></tr><tr><td><strong>Paper size</strong></td><td>Choose the sticker layout (see formats below). Default: <em>A4 - 4 QRs</em>.</td></tr><tr><td><strong>Banner</strong></td><td>Which of your uploaded sticker banners to print. Used by the formats <em>with banner</em>.</td></tr><tr><td><strong>Client Meta</strong></td><td>Comma-separated property keys of your panels to print on each sticker, for example <code>montagevolgorde,level</code>. The value is taken from the panel, or from its design when the panel does not have it. A key found on neither is left out; an empty value prints <code>---</code>.</td></tr></tbody></table><h2 id="paper-formats" tabindex="-1">Paper Formats <a class="header-anchor" href="#paper-formats" aria-label="Permalink to &quot;Paper Formats&quot;">​</a></h2><table><thead><tr><th>Format</th><th>Description</th></tr></thead><tbody><tr><td><strong>A4 - 4 QRs</strong></td><td>A4 landscape, 4 large stickers per page (2 × 2). No banner.</td></tr><tr><td><strong>A4 - 4 QRs (with banner)</strong></td><td>A4 landscape, 4 stickers per page, each with the company banner on top.</td></tr><tr><td><strong>A4 - 12 QRs (with banner)</strong></td><td>A4 portrait, 12 smaller stickers per page (2 columns × 6 rows), each with the banner.</td></tr><tr><td><strong>Dymo (159*104) (with banner)</strong></td><td>One sticker per 159 mm × 104 mm label, for Dymo label printers, with the banner.</td></tr></tbody></table><p><img src="'+o+'" alt="A4 - 4 QRs"></p><ol><li>The QR code. In the PDF it is also a link to the constructible.</li><li>The design name, with its revision, and your own client properties when you pick them in <strong>Client Meta</strong>.</li><li>The short panel ID.</li></ol><p><img src="'+s+'" alt="A4 - 12 QRs (with banner)"></p><ol><li>The banner, from the <strong>Styles</strong> card of the company page.</li></ol><div class="tip custom-block"><p class="custom-block-title">TIP</p><p>The banner image is uploaded on the <strong>Company</strong> page, in the <strong>Styles</strong> card, under <strong>Sticker Banner</strong> (recommended size 1000 × 160 px). You can upload several banners and pick one per report with the <strong>Banner</strong> option.</p></div><h2 id="when-to-use" tabindex="-1">When to Use <a class="header-anchor" href="#when-to-use" aria-label="Permalink to &quot;When to Use&quot;">​</a></h2><p>Print QR stickers and attach them to assemblies or modules in the factory. Workers can scan the QR code with the produuz.it app or any QR reader to instantly open the Viewer for that constructible.</p><h2 id="rack-load-stickers" tabindex="-1">Rack Load Stickers <a class="header-anchor" href="#rack-load-stickers" aria-label="Permalink to &quot;Rack Load Stickers&quot;">​</a></h2><p><strong>Rack Load Stickers</strong> print one label per <a href="/guide/logistics/delivery/">rack load</a>, to fix on the rack itself. Create them in a project&#39;s <strong>Production files</strong>: pick <em>Rack Load Stickers</em> as the report type and select one or more loads in <strong>Rack loads</strong>.</p><ul><li><strong>Format:</strong> PDF, one A4 landscape page per rack load.</li><li><strong>Paper size:</strong> <em>A4 - Single page</em> is the only format.</li><li><strong>Left half:</strong> a large QR code with <em>Scan to open this rack</em> under it. Scanning it opens the rack load on a phone or tablet; in the PDF it is also a clickable link.</li><li><strong>Right half:</strong> the load name, the rack name and type (<em>A-frame, both sides</em>, <em>Single side</em> or <em>Flat bed</em>), the number of panels and the load status; the <strong>Delivery date</strong> in large print when the load has one; the project, project number, client and location; the rack drawing; and the panels in loading order (first row fixed to the frame), with a dot on the strapped rows. The load&#39;s full ID is printed at the bottom.</li></ul><p><img src="'+n+'" alt="A rack load sticker"></p><ol><li>The QR code opens the rack load.</li><li>The delivery date, printed large.</li><li>The rack drawing, with the strapped rows in blue.</li><li>The loading order. A dot marks the strapped rows.</li></ol>',20),d=[l];function h(c,p,m,g,k,u){return t(),r("div",null,d)}const y=e(i,[["render",h]]);export{f as __pageData,y as default};
